import{_ as i,o as l,c as a,Q as e}from"./chunks/framework.b2e9bf53.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"专题/生成式AI/Dify搭建聊天助手.md","filePath":"专题/生成式AI/Dify搭建聊天助手.md","lastUpdated":null}'),t={name:"专题/生成式AI/Dify搭建聊天助手.md"},r=e('<h2 id="通过dify搭建聊天助手-操作手册" tabindex="-1">通过Dify搭建聊天助手-操作手册 <a class="header-anchor" href="#通过dify搭建聊天助手-操作手册" aria-label="Permalink to &quot;通过Dify搭建聊天助手-操作手册&quot;">​</a></h2><p>Dify 支持四种类型的应用，这里以搭建“聊天助手”为例。聊天助手适用于客户服务、在线教育、医疗保健和金融服务等场景，帮助提升工作效率、降低人工成本并改善用户体验。</p><h2 id="dify平台大模型配置步骤" tabindex="-1">Dify平台大模型配置步骤 <a class="header-anchor" href="#dify平台大模型配置步骤" aria-label="Permalink to &quot;Dify平台大模型配置步骤&quot;">​</a></h2><ol><li>登录/注册 Dify</li></ol><p>Dify工作室可能被墙，推荐配置VPN之后再进行登录注册等操作；进入网址<a href="https://dify.ai/zh%EF%BC%8C%E7%82%B9%E5%87%BB%E5%BC%80%E5%A7%8B%E4%BD%BF%E7%94%A8%E3%80%82" target="_blank" rel="noreferrer">https://dify.ai/zh，点击开始使用。</a></p><p>使用GitHub、Google或者邮箱登录；</p><ol start="2"><li>点击右上角头像并选择“设置”。</li><li>进入“模型供应商”页面。</li><li>从列表中选择需要的大模型。</li><li>输入 API Key，点击保存即可完成配置大模型</li></ol><h2 id="什么是-api-key" tabindex="-1">什么是 API Key？ <a class="header-anchor" href="#什么是-api-key" aria-label="Permalink to &quot;什么是 API Key？&quot;">​</a></h2><p>API Key 是与第三方服务交互时使用的认证凭证。配置 API Key 后，您可免费获得一定额度的 Token，用于调用服务。超出免费额度后需要充值，费用通常较低。</p><h3 id="如何获取-api-key" tabindex="-1">如何获取 API Key <a class="header-anchor" href="#如何获取-api-key" aria-label="Permalink to &quot;如何获取 API Key&quot;">​</a></h3><ul><li><p>方案一（不推荐）：通过国外手机号注册openAI API官方账号，并使用visa卡充值额度获取固定额度API key，由于国内防火墙设置还有openAI对虚拟手机号的管控，网络和硬件门槛较高，不推荐。</p></li><li><p>方案二（推荐）：购买API中转额度</p></li></ul><p>推荐一个便捷的 AI 聚合 API 网站：<a href="https://api.bianxie.ai/%E3%80%82%E4%BD%BF%E7%94%A8%E6%B5%81%E7%A8%8B%E5%A6%82%E4%B8%8B%EF%BC%9A" target="_blank" rel="noreferrer">https://api.bianxie.ai/。使用流程如下：</a></p><ol><li>注册并登录：访问网站并完成注册登录。</li><li>获取兑换码：</li></ol><ul><li><p>点击页面上的“钱包”。</p></li><li><p>选择“获取兑换码”。</p></li><li><p>按需选择分类和商品，找到“便携 AI 聚合 API 1 美元兑换码”。</p></li><li><p>购买兑换码后完成兑换。</p></li></ul><ol start="3"><li>获取 API Key：</li></ol><ul><li>进入“令牌”页面。</li><li>复制生成的 API Key。</li></ul><ol start="4"><li>配置 API：</li></ol><ul><li>将复制的 API Key 粘贴到相应平台的设置中。</li><li>API Base 地址填写为：<a href="https://api.bianxie.ai" target="_blank" rel="noreferrer">https://api.bianxie.ai</a>。</li></ul><h2 id="创建聊天助手应用教程" tabindex="-1">创建聊天助手应用教程 <a class="header-anchor" href="#创建聊天助手应用教程" aria-label="Permalink to &quot;创建聊天助手应用教程&quot;">​</a></h2><p>配置完大模型后，即可开始创建聊天助手应用。例如，我们可以构建一个 软件工程师面试助手，帮助开发者模拟面试场景。</p><ul><li>创建应用步骤：</li></ul><ol><li>选择“聊天助手”作为应用类型。</li><li>选择“基础编排”作为编排方式。</li><li>设置应用图标和名称。</li><li>添加应用描述。</li><li>点击保存进行下一步</li><li>提示词编写</li></ol><blockquote><p>提示词解析</p></blockquote><ul><li>明确AI扮演的角色 - 我想让你担任移动端软件开发面试官。</li><li>明确AI需要完成的任务 - 您将向我询问移动端软件开发工程师职位的面试问题。</li><li>明确AI回答的限制 - 我希望你只作为面试官回答。不要一次写出所有的问题。我希望你只对我进行采访。问我问题，等待我的回答。不要写解释。像面试官一样一个一个问我，等我回答。当我回准备好了后，开始提问。</li></ul><ol start="7"><li>应用发布点击保存进行下一步</li></ol><ul><li>运行，生成一个链接，在PC端和移动端的浏览器中均可访问。</li><li>你也可以使用iframe标签将该聊天助手嵌入你现有网页中。</li><li>当然你也可以用API的方式访问该聊天助手，例如你有自己的App，你可以在App中自定义聊天页面样式，调用API来访问该聊天助手。</li></ul>',26),o=[r];function p(n,s,h,A,f,d){return l(),a("div",null,o)}const y=i(t,[["render",p]]);export{u as __pageData,y as default};
